    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    # Join any two 1 markers lying on the same diagonal.
    one_segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                one_segments.append((r1, c1, r2, c2))
                for k in range(abs(r2-r1) + 1):
                    out[r1 + dr*k][c1 + dc*k] = 1

    # A 6 marker intersecting a 1 segment extends in the opposite diagonal
    # direction, across the canvas.
    for r, c in sixes:
        crosses = False
        for r1, c1, r2, c2 in one_segments:
            if abs(r-r1) == abs(c-c1) and abs(r2-r) == abs(c2-c) and (r-r1)*(r2-r1) >= 0 and (c-c1)*(c2-c1) >= 0:
                crosses = True
                slope = (1 if r2 > r1 else -1, 1 if c2 > c1 else -1)
                break
        if crosses:
